      var stageElement = document.getElementById("stage");
      var canvasWrapperElement = document.getElementById("canvasWrapper");
      var designWidth = 828;
      var designHeight = 1792;
      function updateScaleAndPosition() {
        var viewportWidth = stageElement.clientWidth;
        var viewportHeight = stageElement.clientHeight;
        var scaleFactor = Math.min(viewportWidth / designWidth, viewportHeight / designHeight);
        var scaledWidth = designWidth * scaleFactor;
        var scaledHeight = designHeight * scaleFactor;
        var leftOffset = Math.round((viewportWidth - scaledWidth) / 2);
        var topOffset = Math.round((viewportHeight - scaledHeight) / 2);
        canvasWrapperElement.style.transform = "translate(" + leftOffset + "px," + topOffset + "px) scale(" + scaleFactor + ")";
      }
      window.addEventListener("resize", updateScaleAndPosition);
      updateScaleAndPosition();
    })();
